'use client';
import { useMemo, useState } from 'react'; import type { QuizQuestion } from '../../data/question-bank';
const normalize=(text:string)=>text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function SearchQuestions({questions}:{questions:QuizQuestion[]}){const [query,setQuery]=useState(''); const normalized=normalize(query.trim()); const ordered=useMemo(()=>{if(!normalized)return questions;const hits:QuizQuestion[]=[];const rest:QuizQuestion[]=[];for(const item of questions){(normalize(`${item.question} ${Object.values(item.options).join(' ')}`).includes(normalized)?hits:rest).push(item)}return [...hits,...rest]},[normalized,questions]);const count=useMemo(()=>normalized?ordered.filter(x=>normalize(`${x.question} ${Object.values(x.options).join(' ')}`).includes(normalized)).length:0,[normalized,ordered]);const mark=(text:string)=>normalized&&normalize(text).includes(normalized)?<mark>{text}</mark>:text;return <main><header className="hero"><p className="eyebrow">Tra cứu</p><h1>Danh sách 430 câu hỏi</h1><p className="lead">Câu khớp được đưa lên đầu và tô nổi bật.</p></header><section className="searchPanel"><input autoFocus placeholder="Nhập từ khóa, ví dụ: chỉ định thầu" value={query} onChange={e=>setQuery(e.target.value)}/><p>{normalized?`${count} câu phù hợp đang ở đầu danh sách.`:'Đang hiển thị toàn bộ 430 câu.'}</p>{ordered.map(q=>{const hit=normalized&&normalize(`${q.question} ${Object.values(q.options).join(' ')}`).includes(normalized);return <article className={`searchResult ${hit?'searchHit':''}`} key={q.id}><strong>Câu {q.id}</strong><h2>{mark(q.question)}</h2><p>{Object.entries(q.options).map(([key,value])=><span className="optionPreview" key={key}><b>{key}.</b> {mark(value)}</span>)}</p><p>Đáp án: <b>{q.answer}</b></p></article>})}</section></main>}
